const root = document.querySelector('#content');
let me = null, view = '', catalog = { vehicles: [], addresses: [], services: [], googleMapsApiKey: null }, bookings = [], workerProfile = null;
let customerCacheLoaded = false, customerLoadPromise = null, renderSequence = 0;
let deferredInstallPrompt = null, installDialogOpen = false;
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const money = paise => new Intl.NumberFormat('en-IN', { style:'currency', currency:'INR', maximumFractionDigits:0 }).format(Number(paise||0)/100);
const date = x => new Date(x).toLocaleString('en-IN', { dateStyle:'medium', timeStyle:'short' });
const statusText = { CREATED:'Ready to pay', QUOTE_REQUESTED:'Quote in review', QUOTE_PROVIDED:'Quote ready', PAYMENT_PENDING:'Payment pending', PAID:'Paid', ASSIGNING:'Finding a worker', ASSIGNED:'Assigned', WORKER_ON_THE_WAY:'Worker on the way', IN_PROGRESS:'In progress', PHOTOS_UPLOADED:'Photos in review', APPROVED:'Approved', COMPLETED:'Completed', CANCELLED:'Cancelled', REJECTED_PHOTOS:'Photos need retaking', REFUNDED:'Refunded', NO_WORKER_FOUND:'No worker found' };
function statusBadge(status){const label=statusText[status]||String(status||'').replaceAll('_',' ');const tone=['COMPLETED','APPROVED','PAID'].includes(status)?'done':['PAYMENT_PENDING','ASSIGNING','PHOTOS_UPLOADED'].includes(status)?'pending':['CANCELLED','REJECTED_PHOTOS','REFUNDED','NO_WORKER_FOUND'].includes(status)?'cancelled':['ASSIGNED','WORKER_ON_THE_WAY','IN_PROGRESS'].includes(status)?'info':'';return '<span class="badge '+tone+'">'+esc(label)+'</span>'}
async function api(url, opts={}) { const started=performance.now();try{const r=await fetch(url,{credentials:'same-origin',...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});if(r.status===204){if(opts.method&&opts.method!=='GET'&&url.startsWith('/api/v1/'))customerCacheLoaded=false;return null}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request failed');if(opts.method&&opts.method!=='GET'&&url.startsWith('/api/v1/'))customerCacheLoaded=false;return d}finally{console.info('QuickWashHub API',JSON.stringify({path:url.split('?')[0].replace(/\/[a-z0-9_-]{20,}/gi,'/:id'),durationMs:Math.round(performance.now()-started)}))} }
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),3500)}
function isInstalled(){if(window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true)return true;try{return localStorage.getItem('quickwashhub:installed')==='1'}catch{return false}}
function promptKey(){return 'quickwashhub:pwa-install-prompted:'+(me?.id||me?.email||'customer')}
function setInstallButton(){const b=document.querySelector('#install-app');if(!b)return;b.classList.toggle('hidden',!deferredInstallPrompt||isInstalled())}
function closeInstallDialog(markSeen=true){const modal=document.querySelector('#install-dialog');if(modal)modal.remove();installDialogOpen=false;if(markSeen&&me?.role==='CUSTOMER'){try{localStorage.setItem(promptKey(),'1')}catch{}}}
async function installApp(){if(!deferredInstallPrompt){toast('Direct installation is not available in this browser.');return}const promptEvent=deferredInstallPrompt;deferredInstallPrompt=null;setInstallButton();try{await promptEvent.prompt();const choice=await promptEvent.userChoice;if(choice?.outcome==='accepted'){try{localStorage.setItem('quickwashhub:installed','1')}catch{};toast('QuickWashHub is being installed.')}else setInstallButton()}catch{toast('The browser could not open the install prompt.')}closeInstallDialog();}
function showFirstInstallDialog(){if(!me||me.role!=='CUSTOMER'||isInstalled()||installDialogOpen)return;try{if(localStorage.getItem(promptKey()))return}catch{};installDialogOpen=true;const modal=document.createElement('div');modal.className='backdrop';modal.id='install-dialog';modal.setAttribute('role','presentation');modal.innerHTML='<section class="modal install-modal" role="dialog" aria-modal="true" aria-labelledby="install-title"><div class="install-mark" aria-hidden="true">Q</div><div class="eyebrow">QUICK ACCESS</div><h2 id="install-title">Take QuickWashHub with you</h2><p>Install the app for a faster way to book washes and check your service updates.</p>'+(deferredInstallPrompt?'<div class="install-actions"><button class="primary" id="install-now" type="button">Install app</button><button class="text-button" id="install-later" type="button">Maybe later</button></div>':'<p class="install-unavailable">This browser does not offer a direct install prompt. You can continue using QuickWashHub here.</p><button class="secondary" id="install-later" type="button">Continue</button>')+'</section>';document.body.append(modal);modal.querySelector('#install-now')?.addEventListener('click',installApp);modal.querySelector('#install-later').addEventListener('click',()=>closeInstallDialog());modal.addEventListener('click',e=>{if(e.target===modal)closeInstallDialog()});modal.addEventListener('keydown',e=>{if(e.key==='Escape')closeInstallDialog()});try{modal.querySelector('#install-now,#install-later').focus()}catch{};try{localStorage.setItem(promptKey(),'1')}catch{}}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();if(isInstalled())return;deferredInstallPrompt=event;setInstallButton();if(me?.role==='CUSTOMER')setTimeout(showFirstInstallDialog,100)});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;setInstallButton();try{localStorage.setItem('quickwashhub:installed','1')}catch{};closeInstallDialog()});
document.querySelector('#install-app')?.addEventListener('click',installApp);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js?v=14',{updateViaCache:'none'}).catch(()=>{}));
function panel(title,body,action){return '<div class="sectionhead"><h3>'+esc(title)+'</h3></div><div class="panel">'+(body||'<p class="fine">Nothing here yet.</p>')+(action||'')+'</div>'}
function heading(title,desc,button){return '<div class="heading"><div><div class="eyebrow">'+esc(me.role)+'</div><h1>'+esc(title)+'</h1><p>'+esc(desc||'')+'</p></div>'+(button||'')+'</div>'}
function authPage(mode='login', email=''){document.querySelector('#crumb').textContent='Sign in';document.querySelector('#logout').classList.add('hidden');document.querySelector('#user').innerHTML='';document.querySelector('#nav').innerHTML='';document.querySelector('#mobile-nav').classList.add('hidden');const verify=mode==='verify',reset=mode==='reset',register=mode==='register';root.innerHTML='<div class="auth-wrap"><section class="auth-card"><div class="eyebrow">CAR & BIKE CARE, AT YOUR DOOR</div><h1>'+({login:'Sign in to QuickWashHub',register:'Create your account',verify:'Verify your email',reset:'Reset your password',forgot:'Reset your password'}[mode])+'</h1><p>'+({login:'Book and manage your car or bike wash.',register:'Use your email to create a secure account.',verify:'Enter the six-digit code sent to your email.',reset:'Enter the code from your email and choose a new password.',forgot:'We’ll email a password reset code if the account exists.'}[mode])+'</p>'+(mode==='login'?'<div class="google-button" id="google-signin" aria-label="Sign in with Google"></div><div class="auth-divider"><span>or continue with email</span></div>':'')+'<form id="auth-form">'+(register?'<label class="field"><span>Your name</span><input name="name" autocomplete="name" required maxlength="100"></label>':'')+'<label class="field"><span>Email address</span><input name="email" type="email" autocomplete="email" required value="'+esc(email)+'" '+(verify||reset?'readonly':'')+'></label>'+(verify||reset?'<label class="field"><span>Six-digit code</span><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required></label>':'')+((mode==='login'||register||reset)?'<label class="field"><span>'+(reset?'New password':'Password')+'</span><input name="password" type="password" autocomplete="'+(register||reset?'new-password':'current-password')+'" minlength="10" maxlength="128" required></label>':'')+'<button class="primary" type="submit">'+({login:'Sign in',register:'Create account',verify:'Verify email and continue',reset:'Save new password',forgot:'Send reset code'}[mode])+' →</button></form><p class="fine">'+(mode==='login'?'<button class="text-button" id="forgot" type="button">Forgot password?</button>':'')+' '+(mode==='login'?'<button class="text-button" id="register" type="button">Create an account</button>':'<button class="text-button" id="back-login" type="button">Back to sign in</button>')+'</p></section></div>';
 document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{if(mode==='login'){await api('/api/v1/auth/login',{method:'POST',body:JSON.stringify(d)});await boot()}else if(register){await api('/api/v1/auth/register',{method:'POST',body:JSON.stringify(d)});authPage('verify',d.email);toast('Verification code emailed')}else if(verify){await api('/api/v1/auth/verify-email',{method:'POST',body:JSON.stringify(d)});await boot()}else if(mode==='forgot'){await api('/api/v1/auth/password-reset/request',{method:'POST',body:JSON.stringify(d)});authPage('reset',d.email);toast('If the account exists, a code was emailed')}else if(reset){await api('/api/v1/auth/password-reset/confirm',{method:'POST',body:JSON.stringify(d)});authPage('login',d.email);toast('Password updated')}}catch(err){toast(err.message)}};
 document.querySelector('#register')?.addEventListener('click',()=>authPage('register'));document.querySelector('#forgot')?.addEventListener('click',()=>authPage('forgot'));document.querySelector('#back-login')?.addEventListener('click',()=>authPage('login',email));
 if(mode==='login')api('/api/v1/auth/config').then(cfg=>{if(!cfg.googleClientId){document.querySelector('#google-signin')?.classList.add('hidden');return;}const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=()=>{window.google.accounts.id.initialize({client_id:cfg.googleClientId,callback:async result=>{try{await api('/api/v1/auth/google',{method:'POST',body:JSON.stringify({credential:result.credential})});await boot()}catch(err){toast(err.message)}}});const mount=document.querySelector('#google-signin');const card=mount.closest('.auth-card');const cardStyle=getComputedStyle(card);const availableWidth=Math.floor(card.clientWidth-parseFloat(cardStyle.paddingLeft)-parseFloat(cardStyle.paddingRight));window.google.accounts.id.renderButton(mount,{type:'standard',theme:'outline',size:'large',shape:'rectangular',logo_alignment:'left',width:Math.max(200,Math.min(320,availableWidth)),text:'signin_with'})};document.head.append(script)}).catch(()=>{});
}
function nav(){const items=me.role==='CUSTOMER'?[['Overview','⌂'],['Bookings','▣'],['Vehicles','◇'],['Addresses','⌖']]:me.role==='WORKER'?[['Job requests','✦'],['My jobs','▣'],['Earnings','₹']]:[['Bookings','▣'],['Workers','♙'],['Photo review','▧'],['Zones & pricing','⌖'],['Services','✧'],['Campaigns','◷'],['Payouts','₹'],['Reports','▤'],['Audit log','≡']];const html=items.map(x=>'<button class="navlink '+(view===x[0]?'active':'')+'" data-nav="'+esc(x[0])+'" type="button"><span class="nav-icon" aria-hidden="true">'+x[1]+'</span><span class="nav-label">'+esc(x[0])+'</span></button>').join('');document.querySelector('#nav').innerHTML=html;document.querySelector('#mobile-nav').innerHTML=html;document.querySelector('#mobile-nav').classList.remove('hidden');document.querySelectorAll('#nav [data-nav],#mobile-nav [data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render()});}
function setupShell(){document.querySelector('#crumb').textContent=view||'Overview';document.querySelector('#menu-label').textContent=me.role==='CUSTOMER'?'YOUR ACCOUNT':me.role==='WORKER'?'WORKER SPACE':'OPERATIONS';document.querySelector('#logout').classList.remove('hidden');document.querySelector('#user').innerHTML='<i class="avatar">'+esc((me.name||me.email||'U').slice(0,2).toUpperCase())+'</i><div><b>'+esc(me.name||me.email)+'</b><small>'+esc(me.role.toLowerCase())+'</small></div>';document.querySelector('#logout').onclick=async()=>{await api('/api/v1/auth/logout',{method:'POST'});me=null;authPage()};nav();setInstallButton();}
async function refreshCustomer(){if(customerLoadPromise)return customerLoadPromise;customerLoadPromise=Promise.all([api('/api/v1/bootstrap'),api('/api/v1/bookings')]).then(([nextCatalog,nextBookings])=>{catalog=nextCatalog;bookings=nextBookings;customerCacheLoaded=true}).finally(()=>{customerLoadPromise=null});return customerLoadPromise}
function bookingRows(rows,adminView=false){
 if(!rows.length)return '<div class="empty-state"><b>No bookings yet</b>Your washes and booking updates will appear here.</div>';
 const items=rows.map(b=>{let actions='';if(adminView&&b.status==='PAID')actions='<button class="secondary" data-assign="'+esc(b.id)+'" data-zone="'+esc(b.zone?.id||'')+'">Assign worker</button>';if(adminView&&b.status==='QUOTE_REQUESTED')actions='<button class="primary" data-quote="'+esc(b.id)+'">Review and send quote</button>';if(!adminView&&b.status==='CREATED')actions='<button class="primary" data-pay="'+esc(b.id)+'">Pay</button><button class="secondary" data-cancel="'+esc(b.id)+'">Cancel</button>';if(!adminView&&['PAYMENT_PENDING','QUOTE_PROVIDED'].includes(b.status))actions='<button class="primary" data-pay="'+esc(b.id)+'">'+(b.status==='QUOTE_PROVIDED'?'Review quote and pay':'Continue payment')+'</button>';if(!adminView&&['QUOTE_REQUESTED','QUOTE_PROVIDED'].includes(b.status))actions+='<button class="secondary" data-cancel="'+esc(b.id)+'">Cancel request</button>';if(!adminView&&b.status==='COMPLETED'&&!b.rating)actions+='<button class="secondary" data-rate="'+esc(b.id)+'">Rate</button>';if(!adminView&&b.photos)actions+=b.photos.filter(p=>p.status==='APPROVED').map(p=>'<button class="secondary" data-photo-view="'+esc(p.id)+'">'+esc(p.type==='BEFORE'?'Before photo':'After photo')+'</button>').join('');const service=esc(b.service?.name||b.service||'Wash service'),zone=esc(b.zone?.name||b.zone||''),vehicle=esc(b.vehicle?.model?b.vehicle.model+', '+b.vehicle.number:b.vehicle||b.customer?.name||b.customer?.email||b.customer?.phone||'');const total=b.status==='QUOTE_REQUESTED'?'Quote pending':money(b.price);return {b,actions,service,zone,vehicle,total}});
 const table='<div class="tablewrap desktop-booking-table"><table class="data"><thead><tr><th>Service</th><th>Customer / vehicle</th><th>Scheduled</th><th>Status</th><th>Total</th><th>Actions</th></tr></thead><tbody>'+items.map(({b,actions,service,zone,vehicle,total})=>'<tr><td><b>'+service+'</b><small class="subcell">'+zone+'</small></td><td>'+vehicle+(b.solarPropertyType?'<small class="subcell">'+esc(b.solarPropertyType)+' · '+esc(b.solarPanelCount||'panel count TBD')+' panels · '+esc(b.solarRoofType||'')+'</small>':'')+'</td><td>'+esc(date(b.scheduledAt))+'</td><td>'+statusBadge(b.status)+(b.status==='QUOTE_REQUESTED'?'<small class="subcell">'+esc(b.solarAccessNotes||'Waiting for site review')+'</small>':'')+'</td><td>'+total+'</td><td>'+actions+'</td></tr>').join('')+'</tbody></table></div>';
 const cards=adminView?'':'<div class="booking-cards">'+items.map(({b,actions,service,zone,vehicle,total})=>'<article class="booking-card"><div class="booking-card-top"><div><strong>'+service+'</strong><small>'+zone+'</small></div><b class="price">'+total+'</b></div><div class="booking-card-meta"><span>'+esc(date(b.scheduledAt))+'</span><span>'+vehicle+'</span></div>'+(b.status==='QUOTE_REQUESTED'?'<p class="fine">We’re reviewing your site details and will send a quote before payment.</p>':'')+(b.quoteNote?'<p class="fine">'+esc(b.quoteNote)+'</p>':'')+'<div class="booking-card-bottom">'+statusBadge(b.status)+(actions?'<div class="booking-actions">'+actions+'</div>':'')+'</div></article>').join('')+'</div>';
 return '<div class="booking-list '+(adminView?'admin-booking-list':'customer-booking-list')+'">'+table+cards+'</div>';
}
function customerView(){if(view==='Vehicles')return vehicleView();if(view==='Addresses')return addressView();if(view==='Bookings')return heading('Bookings','View upcoming washes, payment status, and completed services.','<button class="primary" data-book>Book a wash</button>')+bookingRows(bookings);const upcoming=bookings.filter(b=>!['COMPLETED','CANCELLED','REFUNDED'].includes(b.status)).slice(0,1),recent=bookings.filter(b=>['COMPLETED','CANCELLED','REFUNDED'].includes(b.status)).slice(0,3);const services=catalog.services.map(s=>'<div class="service"><span class="thumb" aria-hidden="true">'+(s.vehicleType==='BIKE'?'◈':'◇')+'</span><div class="info"><strong>'+esc(s.name)+'</strong><small>'+esc(s.vehicleType)+' · '+s.durationMin+' min · '+esc(s.zoneName)+'</small></div><b class="price">'+money(s.price)+'</b></div>').join('');return heading('Hello, '+(me.name||'there'),'Your next wash is lined up.','<button class="primary" data-book>Book a wash</button>')+'<div class="customer-overview"><div class="overview-main">'+panel('Your next wash',bookingRows(upcoming))+(recent.length?panel('Recent bookings',bookingRows(recent)):'')+'</div><aside class="overview-services">'+panel('Available services',services||'<div class="empty-state"><b>No services available yet</b>Check back after services are added in your area.</div>')+'</aside></div>';}
function vehicleView(){return heading('Your vehicles','Only vehicles you add to your account appear here.')+panel('Add a vehicle','<form id="vehicle-form" class="formrow"><label class="field"><span>Type</span><select name="type"><option>CAR</option><option>BIKE</option></select></label><label class="field"><span>Make and model</span><input name="model" required maxlength="80"></label><label class="field"><span>Registration number</span><input name="number" required maxlength="20"></label><button class="primary">Add vehicle</button></form>')+panel('Saved vehicles',catalog.vehicles.map(v=>'<div class="row"><div class="info"><strong>'+esc(v.model)+'</strong><small>'+esc(v.type)+' · '+esc(v.number)+'</small></div><button class="secondary" data-delete-vehicle="'+esc(v.id)+'">Remove</button></div>').join(''));}
function addressView(){return heading('Service addresses','Pin your location so we can check service availability.')+panel('Add a service address','<form id="address-form"><div class="location-toolbar"><button class="primary" id="use-current-location" type="button">◎ Use my current location</button><span id="location-status" class="fine" role="status">Your location is only used to place this address pin.</span></div><div id="address-map-wrap"><div id="address-map" aria-label="Choose your service location on the map"></div><p class="form-help">Drag the pin or tap the map to adjust the pickup location.</p></div><input type="hidden" name="lat"><input type="hidden" name="lng"><div class="formrow"><label class="field"><span>Save as</span><input name="label" placeholder="Home, work…" autocomplete="address-line1" required maxlength="50"></label><label class="field"><span>Street address or landmark</span><input name="addressLine" placeholder="Choose a pin or enter the street address" autocomplete="street-address" minlength="5" required maxlength="250"></label><label class="field field-wide"><span>Apartment, floor, gate or other directions</span><input name="details" placeholder="Optional details to help the wash partner find you" maxlength="200" autocomplete="address-line2"></label></div><button class="primary" type="submit">Check service area and save →</button></form>')+panel('Saved addresses',catalog.addresses.map(a=>'<div class="row"><div class="info"><strong>'+esc(a.label)+'</strong><small>'+esc(a.fullAddress)+' · '+esc(a.zone?.name||'Service area assigned')+'</small></div><button class="secondary" data-delete-address="'+esc(a.id)+'">Remove</button></div>').join(''));}
let addressMap=null,addressMarker=null,addressGeocoder=null,addressMapsLoad=null;
function loadGoogleMaps(){if(window.google?.maps)return Promise.resolve();if(addressMapsLoad)return addressMapsLoad;if(!catalog.googleMapsApiKey)return Promise.reject(Error('Google Maps is not configured.'));addressMapsLoad=new Promise((resolve,reject)=>{window.quickWashHubGoogleMapsReady=()=>resolve();const script=document.createElement('script');script.src='https://maps.googleapis.com/maps/api/js?key='+encodeURIComponent(catalog.googleMapsApiKey)+'&loading=async&callback=quickWashHubGoogleMapsReady';script.async=true;script.onerror=()=>reject(Error('Google Maps could not load.'));document.head.append(script)});return addressMapsLoad}
function setAddressPin(lat,lng,reverseGeocode=true){const form=document.querySelector('#address-form');if(!form)return;form.elements.lat.value=String(lat);form.elements.lng.value=String(lng);const position={lat,lng};if(addressMap&&addressMarker){addressMarker.setPosition(position);addressMap.setCenter(position);addressMap.setZoom(17)}const status=document.querySelector('#location-status');if(status)status.textContent='Pin selected. Looking up the street address…';if(reverseGeocode&&addressGeocoder){addressGeocoder.geocode({location:position}).then(({results})=>{if(results?.[0]){form.elements.addressLine.value=results[0].formatted_address;if(status)status.textContent='Location found. Add apartment, floor, gate or other directions.'}else if(status)status.textContent='Pin selected. Enter a street address or nearby landmark.'}).catch(()=>{if(status)status.textContent='Pin selected. Enter a street address or nearby landmark.'})}else if(status)status.textContent='Location selected. Add apartment, floor, gate or other directions.'}
function useDeviceLocation(){const status=document.querySelector('#location-status');if(!navigator.geolocation){if(status)status.textContent='This browser does not support device location.';return}if(status)status.textContent='Requesting your location…';navigator.geolocation.getCurrentPosition(position=>setAddressPin(position.coords.latitude,position.coords.longitude),error=>{if(status)status.textContent=error.code===1?'Location permission was denied. Allow location access or choose a pin on the map.':error.code===2?'Your device could not determine its location. Try moving to an open area or choose a map pin.':'Location lookup took too long. Try again or choose a map pin.'},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
async function initializeAddressPicker(){const wrap=document.querySelector('#address-map-wrap'),mapElement=document.querySelector('#address-map');if(!wrap||!mapElement)return;document.querySelector('#use-current-location')?.addEventListener('click',useDeviceLocation);if(!catalog.googleMapsApiKey){wrap.classList.add('map-unavailable');const status=document.querySelector('#location-status');if(status)status.textContent='Use device location to pin the address. Interactive Google Maps will appear once the Maps key is configured.';return}try{await loadGoogleMaps();if(!document.body.contains(mapElement))return;const saved=catalog.addresses[0];const start=saved?{lat:saved.lat,lng:saved.lng}:{lat:20.5937,lng:78.9629};addressMap=new google.maps.Map(mapElement,{center:start,zoom:saved?15:5,mapTypeControl:false,streetViewControl:false,fullscreenControl:false,clickableIcons:false});addressGeocoder=new google.maps.Geocoder();addressMarker=new google.maps.Marker({position:start,map:addressMap,draggable:true,title:'Wash service location'});addressMap.addListener('click',event=>{if(event.latLng)setAddressPin(event.latLng.lat(),event.latLng.lng())});addressMarker.addListener('dragend',event=>{if(event.latLng)setAddressPin(event.latLng.lat(),event.latLng.lng())});if(saved){setAddressPin(saved.lat,saved.lng,false)}}catch(error){wrap.classList.add('map-unavailable');const status=document.querySelector('#location-status');if(status)status.textContent='Google Maps did not load. Use device location or check the Maps API key and website restrictions.'}}
function openBooking(){
 const modal=document.createElement('div');modal.className='backdrop';
 modal.innerHTML='<div class="modal booking-modal"><div class="modalhead"><div><div class="eyebrow">QUICK BOOKING</div><h2>Book a wash</h2><p>We’ll only ask for details you haven’t saved yet.</p></div><button class="close" type="button" aria-label="Close">×</button></div><form id="book-form" class="guided-booking">'+
 '<section class="booking-step"><h3>1. Your contact</h3><div class="formrow"><label class="field"><span>Name</span><input name="fullName" value="'+esc(me.name||'')+'" autocomplete="name" required minlength="2" maxlength="100"></label><label class="field"><span>Mobile number</span><input name="phone" type="tel" inputmode="numeric" autocomplete="tel-national" placeholder="10-digit Indian mobile" value="'+esc((me.phone||'').replace(/^\\+91/,''))+'" pattern="[6-9][0-9]{9}" required></label></div></section>'+
 '<section class="booking-step"><h3>2. What needs washing?</h3><label class="field"><span>Service type</span><select name="category"><option value="VEHICLE">Car or bike wash</option><option value="SOLAR">Solar panel wash · request a quote</option></select></label><div id="vehicle-fields"><div class="formrow"><label class="field"><span>Your vehicle</span><select name="vehicleId">'+catalog.vehicles.map(v=>'<option value="'+esc(v.id)+'">'+esc(v.model)+' · '+esc(v.number)+'</option>').join('')+'<option value="__new">+ Add a vehicle</option></select></label><label class="field hidden" id="new-vehicle-type-wrap"><span>Vehicle type</span><select name="newVehicleType"><option>CAR</option><option>BIKE</option></select></label><label class="field hidden" id="new-vehicle-model-wrap"><span>Make and model</span><input name="newVehicleModel" maxlength="80"></label><label class="field hidden" id="new-vehicle-number-wrap"><span>Registration number</span><input name="newVehicleNumber" maxlength="20"></label></div></div><div id="solar-fields" class="hidden"><div class="formrow"><label class="field"><span>Property type</span><select name="solarPropertyType"><option value="RESIDENTIAL">Residential</option><option value="COMMERCIAL">Commercial</option></select></label><label class="field"><span>Approximate panel count</span><input name="solarPanelCount" type="number" min="1" max="10000" placeholder="If known"></label><label class="field field-wide"><span>Roof type and access details</span><textarea name="solarRoofType" placeholder="For example: flat roof, stair access" minlength="2" maxlength="80"></textarea></label><label class="field field-wide"><span>Anything else about the installation?</span><textarea name="solarAccessNotes" maxlength="1000"></textarea></label></div><p class="form-help">Our team reviews your site details and confirms the final quote before payment.</p></div><label class="field"><span>Available service</span><select name="serviceId" required id="service-choice"></select></label></section>'+
 '<section class="booking-step"><h3>3. Where should we come?</h3><label class="field"><span>Saved address</span><select name="addressId">'+catalog.addresses.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.label)+' · '+esc(a.fullAddress)+'</option>').join('')+'<option value="__new">+ Add a service address</option></select></label><div id="new-address-fields" class="formrow hidden"><div class="location-toolbar"><button class="secondary" id="booking-use-location" type="button">◎ Use my current location</button><span class="fine" id="booking-location-status">We use the device pin to check service availability.</span></div><label class="field"><span>Save this as</span><input name="addressLabel" placeholder="Home, office" maxlength="50"></label><label class="field"><span>Street address or landmark</span><input name="addressLine" autocomplete="street-address" minlength="5" maxlength="250"></label><label class="field field-wide"><span>Gate, floor or directions</span><input name="addressDetails" maxlength="200"></label><input type="hidden" name="lat"><input type="hidden" name="lng"></div></section>'+
 '<section class="booking-step"><h3>4. Choose a time</h3><label class="field"><span>Preferred date and time</span><input type="datetime-local" name="scheduledAt" required></label><div class="total"><span id="service-price-label">Service price</span><b id="service-total"></b></div></section><button class="primary booking-submit">Continue →</button></form></div>';
 document.body.append(modal);const form=modal.querySelector('#book-form');const category=form.elements.category,vehicle=form.elements.vehicleId,address=form.elements.addressId,service=form.elements.serviceId;
 const updateServices=()=>{const addrId=address.value==='__new'?null:address.value,existing=catalog.addresses.find(a=>a.id===addrId),zoneId=existing?.zoneId||zoneAtCoordinates(Number(form.elements.lat.value),Number(form.elements.lng.value))?.id;const selectedVehicle=vehicle.value==='__new'?form.elements.newVehicleType.value:catalog.vehicles.find(x=>x.id===vehicle.value)?.type;const list=catalog.services.filter(s=>s.zoneId===zoneId&&(category.value==='SOLAR'?s.category==='SOLAR':s.category==='VEHICLE'&&s.vehicleType===selectedVehicle));service.innerHTML=list.map(s=>'<option value="'+esc(s.id)+'" data-price="'+(s.price??'')+'">'+esc(s.name)+(s.price!=null?' · '+money(s.price):' · quote after inspection')+'</option>').join('');const solar=category.value==='SOLAR';document.querySelector('#service-price-label').textContent=solar?'Quote':'Service price';document.querySelector('#service-total').textContent=solar?'After site review':money(list[0]?.price);if(!list.length)service.innerHTML='<option value="">No service available in this area yet</option>';};
 const toggleVehicle=()=>{const solar=category.value==='SOLAR';document.querySelector('#vehicle-fields').classList.toggle('hidden',solar);document.querySelector('#solar-fields').classList.toggle('hidden',!solar);vehicle.required=!solar;document.querySelector('#new-vehicle-type-wrap').classList.toggle('hidden',vehicle.value!=='__new'||solar);document.querySelector('#new-vehicle-model-wrap').classList.toggle('hidden',vehicle.value!=='__new'||solar);document.querySelector('#new-vehicle-number-wrap').classList.toggle('hidden',vehicle.value!=='__new'||solar);form.elements.newVehicleModel.required=vehicle.value==='__new'&&!solar;form.elements.newVehicleNumber.required=vehicle.value==='__new'&&!solar;form.elements.solarPanelCount.required=false;form.elements.solarRoofType.required=solar;form.elements.solarPropertyType.required=solar;updateServices()};
 const toggleAddress=()=>{const fresh=address.value==='__new';document.querySelector('#new-address-fields').classList.toggle('hidden',!fresh);address.required=!fresh;for(const n of ['addressLabel','addressLine'])form.elements[n].required=fresh;updateServices()};
 vehicle.onchange=toggleVehicle;form.elements.newVehicleType.onchange=updateServices;category.onchange=toggleVehicle;address.onchange=toggleAddress;service.onchange=()=>{const s=catalog.services.find(x=>x.id===service.value&&x.zoneId===(catalog.addresses.find(a=>a.id===address.value)?.zoneId||zoneAtCoordinates(Number(form.elements.lat.value),Number(form.elements.lng.value))?.id));document.querySelector('#service-total').textContent=category.value==='SOLAR'?'After site review':money(s?.price)};
 const useLocation=()=>{const status=document.querySelector('#booking-location-status');if(!navigator.geolocation){status.textContent='Location is not available. Use your saved address.';return}status.textContent='Finding your location…';navigator.geolocation.getCurrentPosition(p=>{form.elements.lat.value=String(p.coords.latitude);form.elements.lng.value=String(p.coords.longitude);status.textContent=zoneAtCoordinates(p.coords.latitude,p.coords.longitude)?'Location is inside a service area. Add the exact street details.':'This location appears outside current service zones.';updateServices()},()=>{status.textContent='Could not read location. Allow location access or choose a saved address.'},{enableHighAccuracy:true,timeout:12000})};
 document.querySelector('#booking-use-location').onclick=useLocation;const minTime=new Date(Date.now()+60*60*1000);form.elements.scheduledAt.min=new Date(minTime.getTime()-minTime.getTimezoneOffset()*60000).toISOString().slice(0,16);if(!catalog.addresses.length){address.innerHTML='<option value="__new">Add a service address</option>';address.value='__new'}if(!catalog.vehicles.length)vehicle.value='__new';toggleVehicle();toggleAddress();modal.querySelector('.close').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};
 form.onsubmit=async e=>{e.preventDefault();const freshAddress=address.value==='__new',newLat=Number(form.elements.lat.value),newLng=Number(form.elements.lng.value);if(freshAddress&&(!Number.isFinite(newLat)||!Number.isFinite(newLng)))return toast('Use your location to pin the service address.');const payload={fullName:form.elements.fullName.value,phone:form.elements.phone.value,serviceId:service.value,scheduledAt:new Date(form.elements.scheduledAt.value).toISOString(),...(freshAddress?{newAddress:{label:form.elements.addressLabel.value,lat:newLat,lng:newLng,fullAddress:[form.elements.addressLine.value,form.elements.addressDetails.value].filter(Boolean).join(', ')}}:{addressId:address.value})};if(category.value==='VEHICLE'){if(vehicle.value==='__new')payload.newVehicle={type:form.elements.newVehicleType.value,model:form.elements.newVehicleModel.value,number:form.elements.newVehicleNumber.value};else payload.vehicleId=vehicle.value}else{payload.solarPropertyType=form.elements.solarPropertyType.value;if(form.elements.solarPanelCount.value)payload.solarPanelCount=Number(form.elements.solarPanelCount.value);payload.solarRoofType=form.elements.solarRoofType.value;payload.solarAccessNotes=form.elements.solarAccessNotes.value}try{const booking=await api('/api/v1/bookings',{method:'POST',body:JSON.stringify(payload)});modal.remove();await refreshCustomer();view='Bookings';await render();toast(booking.status==='QUOTE_REQUESTED'?'Quote request sent. Our team will review your site details.':'Booking created. Complete payment to confirm.')}catch(error){toast(error.message)}};
}
function zoneAtCoordinates(lat,lng){return catalog.zones?.find(z=>{if(z.centerLat==null||z.centerLng==null||z.radiusKm==null)return false;const rad=x=>x*Math.PI/180,dLat=rad(lat-z.centerLat),dLng=rad(lng-z.centerLng),a=Math.sin(dLat/2)**2+Math.cos(rad(z.centerLat))*Math.cos(rad(lat))*Math.sin(dLng/2)**2;return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))<=z.radiusKm})||null;}
function workerView(){if(view==='Earnings')return heading('Earnings','Wallet ledger balances after completed service.')+panel('Wallet', '<div id="wallet-state">Loading wallet…</div>');return heading(view==='My jobs'?'My assigned jobs':'Available jobs','Jobs are visible only for your approved zones.')+'<div class="workerhero"><div><div class="eyebrow">AVAILABILITY</div><h2 id="availability">'+(workerProfile?.isOnline?'You are online':'You are offline')+'</h2><p>Only approved partners can receive jobs.</p></div><button class="toggle '+(workerProfile?.isOnline?'on':'')+'" id="online-toggle"><span></span></button></div><section id="jobs-state">Loading jobs…</section>';}
function adminView(){if(view==='Photo review')return heading('Photo review','Review before and after wash photos.')+'<section id=admin-bookings>Loading photos…</section>';if(view==='Workers')return heading('Worker partners','Add partners by email, review KYC and activate approved accounts.')+panel('Add worker','<form id="worker-form" class="formrow"><label class="field"><span>Name</span><input name="name" required></label><label class="field"><span>Email</span><input name="email" type="email" placeholder="worker@example.com" required></label><label class="field"><span>Worker type</span><select name="type"><option>PERMANENT</option><option>TEMP</option></select></label><button class="primary">Add worker</button></form>')+'<section id="admin-workers">Loading workers…</section>';if(view==='Zones & pricing')return heading('Zones and pricing','Define active service areas with GeoJSON polygon coordinates.')+panel('Create zone','<form id="zone-form"><label class="field"><span>Zone name</span><input name="name" required></label><label class="field"><span>Base commission percent</span><input name="baseCommissionPct" type="number" min="0" max="100" step="0.1" required></label><label class="field"><span>Polygon JSON (GeoJSON Polygon or MultiPolygon)</span><textarea name="polygon" rows="5" placeholder="{\"type\":\"Polygon\",\"coordinates\":[[[lng,lat],...]]}" required></textarea></label><button class="primary">Create zone</button></form>')+'<section id="zones-state">Loading zones…</section>';if(view==='Services')return heading('Services and prices','Set service durations and zone-specific prices in paise.')+panel('Create service','<form id="service-form" class="formrow"><label class="field"><span>Name</span><input name="name" required></label><label class="field"><span>Vehicle type</span><select name="vehicleType"><option>CAR</option><option>BIKE</option></select></label><label class="field"><span>Duration minutes</span><input name="durationMin" type="number" min="5" max="600" required></label><button class="primary">Create service</button></form>')+'<section id="services-state">Loading services…</section>';if(view==='Campaigns')return heading('Campaigns','Create zone promotions and seasonal worker targets.')+panel('Create campaign','<form id="campaign-form" class="formrow"><label class="field"><span>Name</span><input name="name" required></label><label class="field"><span>Zone</span><select name="zoneId" id="campaign-zones"></select></label><label class="field"><span>Start time</span><input name="startDate" type="datetime-local" required></label><label class="field"><span>End time</span><input name="endDate" type="datetime-local" required></label><label class="field"><span>Surge percent</span><input name="surgePct" type="number" min="0" max="500" value="0"></label><label class="field"><span>Temporary workers needed</span><input name="tempWorkersNeeded" type="number" min="0" value="0"></label><button class="primary">Create campaign</button></form>')+'<section id="campaign-state">Loading campaigns…</section>';if(view==='Reports')return heading('Operations reports','Booking and revenue totals for a selected period.')+'<section id="report-state">Loading report…</section>';if(view==='Audit log')return heading('Admin audit log','Recent administrative actions.')+'<section id="audit-state">Loading audit log…</section>';if(view==='Payouts')return heading('Partner payouts','Create and reconcile manual payouts against the worker ledger.')+'<section id="payouts-state">Loading payouts…</section>';return heading('Operations bookings','Live bookings recorded by signed-in customers.')+'<section id="admin-bookings">Loading bookings…</section>';}
async function render(){if(!me)return authPage();setupShell();const sequence=++renderSequence;if(me.role==='CUSTOMER'){root.innerHTML=customerCacheLoaded?customerView():heading('Loading your account','Getting your latest bookings and addresses…')+'<div class="page-loading"><span></span>Getting your account ready…</div>';bindCommon();if(!customerCacheLoaded)refreshCustomer().then(()=>{if(sequence===renderSequence&&me?.role==='CUSTOMER'){root.innerHTML=customerView();bindCommon()}}).catch(e=>{if(sequence===renderSequence)toast(e.message)});return}try{if(me.role==='WORKER'){root.innerHTML=workerView();bindCommon();const profile=await api('/api/v1/worker/profile');if(sequence!==renderSequence)return;workerProfile=profile;root.innerHTML=workerView();bindCommon();await loadWorkerSection();}else{root.innerHTML=adminView();bindCommon();await loadAdminSection();}}catch(e){if(sequence!==renderSequence)return;root.innerHTML=heading('Could not load this section',e.message)+'<button class="secondary" id="retry">Try again</button>';document.querySelector('#retry').onclick=render;return}if(sequence===renderSequence)bindCommon();}
async function loadWorkerSection(){
 if(view==='Earnings'){
  const w=await api('/api/v1/worker/wallet');
  document.querySelector('#wallet-state').innerHTML='<p>Available balance: <b>'+money(w.balance)+'</b></p>'+bookingRows(w.ledger.map(x=>({service:x.type,vehicle:'',scheduledAt:x.createdAt,status:x.type,price:x.amount})));
  return;
 }
 const jobs=await api(view==='My jobs'?'/api/v1/worker/bookings':'/api/v1/worker/jobs');
 const cards=jobs.map(b=>{
  let action='';
  if(view!=='My jobs') action='<button class="primary" data-accept="'+esc(b.id)+'">Accept job</button>';
  else if(b.status==='ASSIGNED') action='<button class="secondary" data-status="'+esc(b.id)+'" data-next="WORKER_ON_THE_WAY">On the way</button>';
  else if(b.status==='WORKER_ON_THE_WAY') action='<button class="secondary" data-status="'+esc(b.id)+'" data-next="IN_PROGRESS">Start wash</button>';
  else if(b.status==='REJECTED_PHOTOS') action='<button class="secondary" data-status="'+esc(b.id)+'" data-next="IN_PROGRESS">Retake photos</button>';
  else if(b.status==='IN_PROGRESS') action='<form class="photo-form" data-photo-booking="'+esc(b.id)+'"><label class="field"><span>Before or after</span><select name="type"><option>BEFORE</option><option>AFTER</option></select></label><label class="field"><span>Choose job photos</span><input name="files" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label><button class="primary">Upload photos</button></form>';
  else action='<span class="fine">Waiting for admin photo review.</span>';
  return '<div class="job"><div class="jobtop"><b>'+esc(b.service?.name||'Wash booking')+'</b><small>'+esc(date(b.scheduledAt))+'</small></div><div class="jobdetails"><span>Vehicle<b>'+esc((b.vehicle?.model||'')+' · '+(b.vehicle?.number||''))+'</b></span><span>Area<b>'+esc(b.zone?.name||'')+'</b></span><span>Customer address<b>'+esc(b.address?.fullAddress||'Assigned booking')+'</b></span><span>Status<b>'+esc(b.status.replaceAll('_',' '))+'</b></span><span>Worker earning<b>'+money(b.workerEarning)+'</b></span></div>'+action+'</div>';
 }).join('');
 document.querySelector('#jobs-state').innerHTML=cards||'<div class="panel"><p class="fine">No jobs found for this view.</p></div>';
}
async function loadAdminSection(){if(view==='Photo review'){const photos=await api('/api/v1/admin/photos');document.querySelector('#admin-bookings').innerHTML=panel('Photos awaiting review',photos.map(p=>'<div class="row"><div class="info"><strong>'+esc(p.type)+' photo · '+esc(p.booking.service.name)+'</strong><small>'+esc(p.booking.customer.phone)+' · '+esc(date(p.capturedAt))+'</small></div><button class="secondary" data-photo-view="'+esc(p.id)+'">View</button><button class="secondary" data-photo-review="'+esc(p.id)+'" data-decision="APPROVED">Approve</button><button class="secondary" data-photo-review="'+esc(p.id)+'" data-decision="REJECTED">Reject</button></div>').join(''));bindPhotoReview();return}if(view==='Workers'){const items=await api('/api/v1/admin/workers');document.querySelector('#admin-workers').innerHTML=panel('Worker list',items.map(w=>'<div class="row"><div class="info"><strong>'+esc(w.user.name||w.user.email)+'</strong><small>'+esc(w.type)+' · KYC '+esc(w.kycStatus)+' · '+(w.isOnline?'online':'offline')+'</small></div>'+(w.kycStatus!=='APPROVED'?'<button class="secondary" data-kyc="'+esc(w.id)+'">Approve KYC</button>':'')+'<button class="secondary" data-block="'+esc(w.id)+'">Block</button></div>').join(''));return}if(view==='Zones & pricing'){const [zones,workers]=await Promise.all([api('/api/v1/admin/zones'),api('/api/v1/admin/workers')]);document.querySelector('#zones-state').innerHTML=panel('Configured service areas',zones.map(z=>'<div class="row"><div class="info"><strong>'+esc(z.name)+'</strong><small>'+z.baseCommissionPct+'% commission · '+(z.isActive?'active':'inactive')+'</small></div><button class="secondary" data-zone-toggle="'+esc(z.id)+'" data-active="'+z.isActive+'">'+(z.isActive?'Deactivate':'Activate')+'</button></div>').join(''))+panel('Assign workers to a zone','<form id="worker-zone-form" class="formrow"><label class="field"><span>Worker</span><select name="workerId">'+workers.map(w=>'<option value="'+esc(w.id)+'">'+esc(w.user.name||w.user.email)+'</option>').join('')+'</select></label><label class="field"><span>Zone</span><select name="zoneId">'+zones.map(z=>'<option value="'+esc(z.id)+'">'+esc(z.name)+'</option>').join('')+'</select></label><button class="primary">Assign zone</button></form>');return}if(view==='Services'){const services=await api('/api/v1/admin/services'),zones=await api('/api/v1/admin/zones');document.querySelector('#services-state').innerHTML=panel('Zone prices',services.map(s=>'<div class="row"><div class="info"><strong>'+esc(s.name)+' · '+esc(s.vehicleType)+'</strong><small>'+s.durationMin+' min · '+s.prices.map(p=>esc(p.zone.name)+': '+money(p.price)).join(' · ')+'</small></div></div>').join(''))+panel('Set a zone price','<form id="price-form" class="formrow"><label class="field"><span>Zone</span><select name="zoneId">'+zones.map(z=>'<option value="'+esc(z.id)+'">'+esc(z.name)+'</option>').join('')+'</select></label><label class="field"><span>Service</span><select name="serviceId">'+services.map(s=>'<option value="'+esc(s.id)+'" data-type="'+esc(s.vehicleType)+'">'+esc(s.name)+'</option>').join('')+'</select></label><label class="field"><span>Price (₹)</span><input name="price" type="number" min="1" step="1" required></label><button class="primary">Save price</button></form>');return}if(view==='Campaigns'){const [campaigns,zones]=await Promise.all([api('/api/v1/admin/campaigns'),api('/api/v1/admin/zones')]);document.querySelector('#campaign-zones').innerHTML=zones.map(z=>'<option value="'+esc(z.id)+'">'+esc(z.name)+'</option>').join('');document.querySelector('#campaign-state').innerHTML=panel('Campaign list',campaigns.map(c=>'<div class="row"><div class="info"><strong>'+esc(c.name)+'</strong><small>'+esc(c.zone.name)+' · '+esc(date(c.startDate))+' – '+esc(date(c.endDate))+' · '+c.surgePct+'% surge · '+c.tempWorkersNeeded+' temporary partners</small></div></div>').join(''));return}if(view==='Reports'){const report=await api('/api/v1/admin/reports/summary');document.querySelector('#report-state').innerHTML=panel('Last 30 days','<p>Bookings: <b>'+report.bookings+'</b></p><p>Gross service value: <b>'+money(report.revenuePaise)+'</b></p>'+report.byStatus.map(x=>'<div class="row"><div class="info"><strong>'+esc(x.status.replaceAll('_',' '))+'</strong><small>'+x.count+' bookings</small></div><b>'+money(x.amountPaise)+'</b></div>').join(''));return}if(view==='Audit log'){const logs=await api('/api/v1/admin/audit-logs');document.querySelector('#audit-state').innerHTML=panel('Recent admin changes',logs.map(x=>'<div class="row"><div class="info"><strong>'+esc(x.action)+' · '+esc(x.entity)+'</strong><small>'+esc(x.admin.name||x.admin.email||x.admin.phone)+' · '+esc(date(x.createdAt))+'</small></div></div>').join(''));return}if(view==='Payouts'){const p=await api('/api/v1/admin/payouts'),w=await api('/api/v1/admin/workers');document.querySelector('#payouts-state').innerHTML=panel('Create payout request','<form id="payout-form" class="formrow"><label class="field"><span>Worker</span><select name="workerId">'+w.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.user.name||x.user.phone)+'</option>').join('')+'</select></label><label class="field"><span>Amount (₹)</span><input name="amount" type="number" min="1" step="1" required></label><button class="primary">Create payout</button></form>')+panel('Payout ledger',p.map(x=>'<div class="row"><div class="info"><strong>'+esc(x.worker.user.name||x.worker.user.phone)+'</strong><small>'+esc(x.status)+' '+esc(x.utr||'')+'</small></div><b>'+money(x.amount)+'</b>'+(x.status==='PENDING'?'<button class="secondary" data-paid="'+esc(x.id)+'">Mark paid</button>':'')+'</div>').join(''));return}const rows=await api('/api/v1/admin/bookings');document.querySelector('#admin-bookings').innerHTML=panel('Bookings',bookingRows(rows,true));}
function bindCommon(){bindPhotoReview();initializeAddressPicker();document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{openBooking()});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/bookings/'+encodeURIComponent(b.dataset.cancel)+'/cancel',{method:'POST'});await render();toast('Booking cancelled')}catch(e){toast(e.message)}});document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>pay(b.dataset.pay));document.querySelector('#vehicle-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/v1/vehicles',{method:'POST',body:JSON.stringify(d)});await render();toast('Vehicle added')}catch(x){toast(x.message)}});document.querySelector('#address-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.lat=Number(d.lat);d.lng=Number(d.lng);if(!Number.isFinite(d.lat)||!Number.isFinite(d.lng)||d.lat < -90||d.lat > 90||d.lng < -180||d.lng > 180)return toast('Select your location on the map or use your device location first.');d.fullAddress=d.addressLine+(d.details?' — '+d.details:'');try{const saved=await api('/api/v1/addresses',{method:'POST',body:JSON.stringify(d)});catalog.addresses.push(saved);root.innerHTML=addressView();bindCommon();toast('Address saved')}catch(x){toast(x.message)}});document.querySelector('#online-toggle')?.addEventListener('click',async()=>{try{workerProfile=await api('/api/v1/worker/online',{method:'PATCH',body:JSON.stringify({online:!workerProfile.isOnline})});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/worker/jobs/'+encodeURIComponent(b.dataset.accept)+'/accept',{method:'POST'});await render();toast('Job accepted')}catch(e){toast(e.message)}});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/worker/bookings/'+encodeURIComponent(b.dataset.status)+'/status',{method:'PATCH',body:JSON.stringify({status:b.dataset.next})});await render();toast('Booking status updated')}catch(e){toast(e.message)}});document.querySelectorAll('[data-photo-booking]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await uploadPhotos(f.dataset.photoBooking,f.elements.type.value,Array.from(f.elements.files.files));await render();toast('Photos uploaded for admin review')}catch(x){toast(x.message)}});document.querySelector('#campaign-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const data={name:f.get('name'),zoneId:f.get('zoneId'),startDate:new Date(f.get('startDate')).toISOString(),endDate:new Date(f.get('endDate')).toISOString(),surgePct:Number(f.get('surgePct')),tempWorkersNeeded:Number(f.get('tempWorkersNeeded'))};try{await api('/api/v1/admin/campaigns',{method:'POST',body:JSON.stringify(data)});await render();toast('Campaign created')}catch(x){toast(x.message)}});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=async()=>{const stars=Number(prompt('Rate the completed service from 1 to 5 stars'));if(!stars)return;try{await api('/api/v1/bookings/'+encodeURIComponent(b.dataset.rate)+'/rating',{method:'POST',body:JSON.stringify({stars})});await render();toast('Rating saved')}catch(e){toast(e.message)}});document.querySelector('#worker-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/v1/admin/workers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});await render();toast('Worker account created. They can set a password or sign in with Google using this email.')}catch(x){toast(x.message)}});document.querySelector('#worker-zone-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/workers/'+encodeURIComponent(f.get('workerId'))+'/zones/'+encodeURIComponent(f.get('zoneId')),{method:'PUT'});toast('Worker assigned to zone')}catch(x){toast(x.message)}});document.querySelector('#zone-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/zones',{method:'POST',body:JSON.stringify({name:f.get('name'),baseCommissionPct:Number(f.get('baseCommissionPct')),polygon:JSON.parse(f.get('polygon'))})});await render();toast('Zone created')}catch(x){toast(x.message)}});document.querySelectorAll('[data-zone-toggle]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/zones/'+encodeURIComponent(b.dataset.zoneToggle),{method:'PATCH',body:JSON.stringify({isActive:b.dataset.active!=='true'})});await render()}catch(e){toast(e.message)}});document.querySelector('#service-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.durationMin=Number(d.durationMin);try{await api('/api/v1/admin/services',{method:'POST',body:JSON.stringify(d)});await render();toast('Service created')}catch(x){toast(x.message)}});document.querySelector('#price-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),type=e.currentTarget.elements.serviceId.selectedOptions[0].dataset.type;try{await api('/api/v1/admin/zones/'+encodeURIComponent(f.get('zoneId'))+'/prices/'+encodeURIComponent(f.get('serviceId')),{method:'PUT',body:JSON.stringify({price:Math.round(Number(f.get('price'))*100),vehicleType:type})});await render();toast('Zone price saved')}catch(x){toast(x.message)}});document.querySelector('#payout-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/payouts',{method:'POST',body:JSON.stringify({workerId:f.get('workerId'),amount:Math.round(Number(f.get('amount'))*100)})});await render();toast('Payout created')}catch(x){toast(x.message)}});document.querySelectorAll('[data-kyc]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/workers/'+encodeURIComponent(b.dataset.kyc)+'/kyc',{method:'PATCH',body:JSON.stringify({status:'APPROVED'})});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/workers/'+encodeURIComponent(b.dataset.block)+'/block',{method:'PATCH'});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=async()=>{try{const workers=await api('/api/v1/admin/workers'),eligible=workers.filter(w=>w.isOnline&&w.kycStatus==='APPROVED'&&w.zones.some(z=>z.zoneId===b.dataset.zone));if(!eligible.length)return toast('No approved online worker is assigned to this zone.');const choice=prompt('Choose worker number:\n'+eligible.map((w,i)=>(i+1)+'. '+(w.user.name||w.user.email)).join('\n'));const worker=eligible[Number(choice)-1];if(!worker)return;await api('/api/v1/admin/bookings/'+encodeURIComponent(b.dataset.assign)+'/assign',{method:'POST',body:JSON.stringify({workerId:worker.id})});await render();toast('Booking assigned')}catch(e){toast(e.message)}});document.querySelectorAll('[data-paid]').forEach(b=>b.onclick=async()=>{const utr=prompt('Enter the bank/UPI transfer reference (UTR):');if(!utr)return;try{await api('/api/v1/admin/payouts/'+encodeURIComponent(b.dataset.paid)+'/mark-paid',{method:'POST',body:JSON.stringify({utr})});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-delete-vehicle]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this vehicle?'))return;try{await api('/api/v1/vehicles/'+encodeURIComponent(b.dataset.deleteVehicle),{method:'DELETE'});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-delete-address]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this address?'))return;try{await api('/api/v1/addresses/'+encodeURIComponent(b.dataset.deleteAddress),{method:'DELETE'});catalog.addresses=catalog.addresses.filter(a=>a.id!==b.dataset.deleteAddress);root.innerHTML=addressView();bindCommon()}catch(e){toast(e.message)}});}
async function pay(id){try{const order=await api('/api/v1/bookings/'+encodeURIComponent(id)+'/payment-order',{method:'POST'});if(!window.Cashfree){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://sdk.cashfree.com/js/v3/cashfree.js';s.onload=resolve;s.onerror=reject;document.head.append(s)})}const cashfree=window.Cashfree({mode:order.mode});await cashfree.checkout({paymentSessionId:order.paymentSessionId,redirectTarget:'_self'})}catch(e){toast(e.message)}}
async function uploadPhotos(bookingId,type,files){if(!files.length)throw Error('Choose at least one photo.');const location=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude}),()=>reject(Error('Location permission is needed to attach job GPS.')),{enableHighAccuracy:true,timeout:10000}));for(const file of files){if(file.size>10*1024*1024)throw Error('Each image must be 10 MB or smaller.');const signed=await api('/api/v1/worker/bookings/'+encodeURIComponent(bookingId)+'/photos/presign',{method:'POST',body:JSON.stringify({type,contentType:file.type})});const uploaded=await fetch(signed.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!uploaded.ok)throw Error('Could not upload a photo to private storage. Check storage bucket CORS.');await api('/api/v1/worker/bookings/'+encodeURIComponent(bookingId)+'/photos',{method:'POST',body:JSON.stringify({type,objectKey:signed.objectKey,capturedAt:new Date(file.lastModified||Date.now()).toISOString(),lat:location.lat,lng:location.lng})})}}
function bindPhotoReview(){document.querySelectorAll('[data-photo-view]').forEach(b=>b.onclick=async()=>{try{const d=await api('/api/v1/photos/'+encodeURIComponent(b.dataset.photoView)+'/view');const modal=document.createElement('div');modal.className='backdrop';modal.innerHTML='<div class="modal"><button class="close">Close</button><img class="preview-image" alt="Booking evidence" src="'+esc(d.url)+'"></div>';document.body.append(modal);modal.querySelector('.close').onclick=()=>modal.remove()}catch(e){toast(e.message)}});document.querySelectorAll('[data-photo-review]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/photos/'+encodeURIComponent(b.dataset.photoReview),{method:'PATCH',body:JSON.stringify({status:b.dataset.decision})});await render();toast('Photo review saved')}catch(e){toast(e.message)}})}
async function boot(){const started=performance.now();try{me=await api('/api/v1/me');if(me.customerSnapshot){catalog=me.customerSnapshot.catalog;bookings=me.customerSnapshot.bookings;customerCacheLoaded=true;delete me.customerSnapshot}view=me.role==='CUSTOMER'?'Overview':me.role==='WORKER'?'Job requests':'Bookings';await render();console.info('QuickWashHub dashboard ready',Math.round(performance.now()-started)+'ms');if(me.role==='CUSTOMER')setTimeout(showFirstInstallDialog,1200)}catch{me=null;authPage()}}
boot();
